`timescale 1ns / 1ps

// -----------------------------------------------------------------------------
// GUI-driven CPU simulation testbench
//
// Reads D:/assembler/program.hex generated by the Python assembler GUI,
// streams the words through the CPU's REAL UART RX/program-loader path, waits
// for HLT (or a bounded timeout), and writes a GUI-compatible JSON file to
// D:/assembler/simulation_result.json.
//
// Expected GUI JSON schema:
//   pc:        hex string, e.g. "0x00000040"
//   halt:      1 when the CPU reached HLT, otherwise 0
//   registers: array of 32 hex strings, R0 through R31
// Additional status/debug fields are included and ignored by older GUIs.
// -----------------------------------------------------------------------------

`ifndef CPU_PROGRAM_HEX_PATH
`define CPU_PROGRAM_HEX_PATH "D:/assembler/program.hex"
`endif

`ifndef CPU_RESULT_JSON_PATH
`define CPU_RESULT_JSON_PATH "D:/assembler/simulation_result.json"
`endif

module cpu_sim_tb;

    localparam integer CLK_PERIOD_NS          = 10; // 100 MHz
    localparam integer CLK_FREQ_HZ            = 100_000_000;
    localparam integer UART_BAUD              = 921600;
    localparam integer BIT_CYCLES              = CLK_FREQ_HZ / UART_BAUD; // 108
    localparam integer MAX_PROGRAM_WORDS       = 4096;
    localparam integer LOAD_TIMEOUT_CYCLES     = 2000;
    localparam integer EXEC_TIMEOUT_CYCLES     = 1000000;

    // Result codes passed to write_result_json:
    // 0 HALTED, 1 TIMEOUT, 2 FILE_ERROR, 3 LOAD_TIMEOUT,
    // 4 MALFORMED_HEX, 5 PROGRAM_TOO_LARGE, 6 EMPTY_PROGRAM,
    // 7 UNKNOWN_STATE.

    reg clk;
    reg reset;
    reg uart_rx;
    wire uart_tx;

    wire [31:0] debug_pc;
    wire [31:0] debug_instruction;
    wire [31:0] debug_alu;
    wire        debug_reg_write;
    wire [4:0]  debug_reg_number;
    wire [31:0] debug_reg_data;
    wire        debug_mem_read;
    wire        debug_mem_write;
    wire [31:0] debug_mem_address;
    wire [31:0] debug_mem_write_data;
    wire        debug_branch_taken;
    wire        debug_jump_taken;
    wire        debug_stall;
    wire        debug_halted;

    reg [31:0] program_mem [0:MAX_PROGRAM_WORDS-1];
    reg [31:0] json_registers [0:31];

    integer hex_fd;
    integer result_fd;
    integer scan_result;
    integer extra_scan_result;
    integer program_words;
    integer i;
    integer b;
    integer wait_cycles;
    integer exec_cycles;
    integer status_code;
    integer saw_end_marker;
    integer malformed_hex;
    integer program_too_large;
    reg [31:0] scan_word;

    cpu_top DUT (
        .clk(clk),
        .reset(reset),
        .uart_rx_pin(uart_rx),
        .uart_tx_pin(uart_tx),
        .debug_pc(debug_pc),
        .debug_instruction(debug_instruction),
        .debug_alu(debug_alu),
        .debug_reg_write(debug_reg_write),
        .debug_reg_number(debug_reg_number),
        .debug_reg_data(debug_reg_data),
        .debug_mem_read(debug_mem_read),
        .debug_mem_write(debug_mem_write),
        .debug_mem_address(debug_mem_address),
        .debug_mem_write_data(debug_mem_write_data),
        .debug_branch_taken(debug_branch_taken),
        .debug_jump_taken(debug_jump_taken),
        .debug_stall(debug_stall),
        .debug_halted(debug_halted)
    );

    always #(CLK_PERIOD_NS / 2) clk = ~clk;

    // UART format is 8-N-1. The loader expects each 32-bit word MSB byte first;
    // within each UART byte, bits travel least-significant bit first.
    task send_uart_byte;
        input [7:0] value;
        integer bit_index;
        begin
            @(negedge clk);
            uart_rx = 1'b0; // start bit
            repeat (BIT_CYCLES) @(negedge clk);

            for (bit_index = 0; bit_index < 8; bit_index = bit_index + 1) begin
                uart_rx = value[bit_index];
                repeat (BIT_CYCLES) @(negedge clk);
            end

            uart_rx = 1'b1; // stop bit
            repeat (BIT_CYCLES) @(negedge clk);
        end
    endtask

    task send_uart_word;
        input [31:0] value;
        begin
            send_uart_byte(value[31:24]);
            send_uart_byte(value[23:16]);
            send_uart_byte(value[15:8]);
            send_uart_byte(value[7:0]);
        end
    endtask

    // Create a valid JSON result even for timeout/input errors so the GUI can
    // display the latest state. Unknown HDL values are emitted as 0 in the
    // registers array (which the GUI requires to be numeric) and are counted
    // explicitly in unknown_register_count/status.
    task write_result_json;
        input integer requested_status;
        input integer cycle_count;
        integer k;
        integer unknown_register_count;
        integer effective_status;
        integer halt_value;
        integer error_count;
        reg [31:0] json_pc;
        reg [31:0] json_instruction;
        reg [31:0] temp_reg;
        begin
            unknown_register_count = 0;
            for (k = 0; k < 32; k = k + 1) begin
                temp_reg = DUT.REG_FILE.registers[k];
                if ((^temp_reg) === 1'bx) begin
                    json_registers[k] = 32'b0;
                    unknown_register_count = unknown_register_count + 1;
                end else begin
                    json_registers[k] = temp_reg;
                end
            end

            json_pc = debug_pc;
            if ((^json_pc) === 1'bx)
                json_pc = 32'b0;

            json_instruction = debug_instruction;
            if ((^json_instruction) === 1'bx)
                json_instruction = 32'b0;

            effective_status = requested_status;
            if ((requested_status == 0) && (unknown_register_count != 0))
                effective_status = 7;

            halt_value = (debug_halted === 1'b1) ? 1 : 0;
            error_count = (effective_status == 0) ? 0 : 1;

            result_fd = $fopen(`CPU_RESULT_JSON_PATH, "w");
            if (result_fd == 0) begin
                $display("CPU_SIM: ERROR: Cannot create JSON result: %s", `CPU_RESULT_JSON_PATH);
            end else begin
                $fwrite(result_fd, "{\n");
                $fwrite(result_fd, "  \"pc\": \"0x%08h\",\n", json_pc);
                $fwrite(result_fd, "  \"halt\": %0d,\n", halt_value);

                case (effective_status)
                    0: $fwrite(result_fd, "  \"status\": \"HALTED\",\n");
                    1: $fwrite(result_fd, "  \"status\": \"TIMEOUT\",\n");
                    2: $fwrite(result_fd, "  \"status\": \"FILE_ERROR\",\n");
                    3: $fwrite(result_fd, "  \"status\": \"LOAD_TIMEOUT\",\n");
                    4: $fwrite(result_fd, "  \"status\": \"MALFORMED_HEX\",\n");
                    5: $fwrite(result_fd, "  \"status\": \"PROGRAM_TOO_LARGE\",\n");
                    6: $fwrite(result_fd, "  \"status\": \"EMPTY_PROGRAM\",\n");
                    default: $fwrite(result_fd, "  \"status\": \"UNKNOWN_STATE\",\n");
                endcase

                $fwrite(result_fd, "  \"errors\": %0d,\n", error_count);
                $fwrite(result_fd, "  \"program_words\": %0d,\n", program_words);
                $fwrite(result_fd, "  \"execution_cycles\": %0d,\n", cycle_count);
                $fwrite(result_fd, "  \"last_instruction\": \"0x%08h\",\n", json_instruction);
                $fwrite(result_fd, "  \"unknown_register_count\": %0d,\n", unknown_register_count);
                $fwrite(result_fd, "  \"registers\": [\n");

                for (k = 0; k < 32; k = k + 1) begin
                    if (k == 31)
                        $fwrite(result_fd, "    \"0x%08h\"\n", json_registers[k]);
                    else
                        $fwrite(result_fd, "    \"0x%08h\",\n", json_registers[k]);
                end

                $fwrite(result_fd, "  ]\n");
                $fwrite(result_fd, "}\n");
                $fclose(result_fd);
                $display("CPU_SIM: JSON_RESULT=%s", `CPU_RESULT_JSON_PATH);
                $display("CPU_SIM: STATUS=%0d HALT=%0d PC=0x%08h WORDS=%0d CYCLES=%0d",
                         effective_status, halt_value, json_pc, program_words, cycle_count);
                $display("CPU_SIM: UNKNOWN_REGISTERS=%0d", unknown_register_count);
            end
        end
    endtask

    initial begin
        clk = 1'b0;
        reset = 1'b1;
        uart_rx = 1'b1;
        program_words = 0;
        wait_cycles = 0;
        exec_cycles = 0;
        status_code = 0;
        saw_end_marker = 0;
        malformed_hex = 0;
        program_too_large = 0;
        scan_result = 1;
        extra_scan_result = 0;
        scan_word = 32'b0;

        $display("============================================================");
        $display("CPU GUI SIMULATION: program.hex -> UART RX -> CPU -> JSON");
        $display("HEX input : %s", `CPU_PROGRAM_HEX_PATH);
        $display("JSON output: %s", `CPU_RESULT_JSON_PATH);
        $display("============================================================");

        // Allow reset to reach the CPU and UART before attempting file access.
        repeat (12) @(negedge clk);

        hex_fd = $fopen(`CPU_PROGRAM_HEX_PATH, "r");
        if (hex_fd == 0) begin
            $display("CPU_SIM: ERROR: Cannot open program.hex: %s", `CPU_PROGRAM_HEX_PATH);
            status_code = 2;
        end else begin
            // The GUI writes one 8-digit machine word per line and DOES NOT
            // include the loader's FFFFFFFF end marker. Read until EOF and
            // append that marker ourselves during UART transmission.
            scan_result = 1;
            while ((scan_result == 1) && (!$feof(hex_fd)) &&
                   (program_words < MAX_PROGRAM_WORDS) && (saw_end_marker == 0)) begin
                scan_result = $fscanf(hex_fd, "%h", scan_word);
                if (scan_result == 1) begin
                    if (scan_word == 32'hFFFFFFFF) begin
                        saw_end_marker = 1; // tolerate files that already contain the marker
                    end else begin
                        program_mem[program_words] = scan_word;
                        program_words = program_words + 1;
                    end
                end else if (scan_result == 0) begin
                    malformed_hex = 1;
                end
            end

            // If the array filled, check one extra token to distinguish an
            // exactly-full image from an image larger than instruction memory.
            if ((program_words == MAX_PROGRAM_WORDS) && (saw_end_marker == 0) &&
                (malformed_hex == 0) && (!$feof(hex_fd))) begin
                extra_scan_result = $fscanf(hex_fd, "%h", scan_word);
                if (extra_scan_result == 1) begin
                    if (scan_word == 32'hFFFFFFFF)
                        saw_end_marker = 1;
                    else
                        program_too_large = 1;
                end else if (extra_scan_result == 0) begin
                    malformed_hex = 1;
                end
            end
            $fclose(hex_fd);

            if (malformed_hex != 0)
                status_code = 4;
            else if (program_too_large != 0)
                status_code = 5;
            else if (program_words == 0)
                status_code = 6;
        end

        if (status_code != 0) begin
            write_result_json(status_code, 0);
            $display("CPU_SIM: Simulation did not start because input validation failed.");
            $finish;
        end

        $display("CPU_SIM: Loaded %0d instruction words from program.hex.", program_words);
        $display("CPU_SIM: Releasing UART reset before transmission.");
        reset = 1'b0;
        repeat (20) @(negedge clk);

        // Stream instructions over the same UART path used by the physical FPGA.
        for (i = 0; i < program_words; i = i + 1) begin
            send_uart_word(program_mem[i]);
        end
        send_uart_word(32'hFFFFFFFF); // loader end-of-program marker
        uart_rx = 1'b1;

        $display("CPU_SIM: UART upload sent; waiting for program_loaded.");
        wait_cycles = 0;
        while ((DUT.program_loaded !== 1'b1) && (wait_cycles < LOAD_TIMEOUT_CYCLES)) begin
            @(posedge clk);
            wait_cycles = wait_cycles + 1;
        end

        if (DUT.program_loaded !== 1'b1) begin
            $display("CPU_SIM: ERROR: UART loader did not assert program_loaded.");
            write_result_json(3, 0);
            $finish;
        end

        $display("CPU_SIM: Program loaded. Waiting for CPU HLT (max %0d cycles).", EXEC_TIMEOUT_CYCLES);
        exec_cycles = 0;
        while ((debug_halted !== 1'b1) && (exec_cycles < EXEC_TIMEOUT_CYCLES)) begin
            @(posedge clk);
            exec_cycles = exec_cycles + 1;
        end

        // Let any instructions already in the pipeline drain before sampling state.
        repeat (8) @(posedge clk);
        #1;

        if (debug_halted === 1'b1) begin
            $display("CPU_SIM: HALT reached at PC=0x%08h after %0d execution cycles.", debug_pc, exec_cycles);
            write_result_json(0, exec_cycles);
        end else begin
            $display("CPU_SIM: TIMEOUT at PC=0x%08h INSTR=0x%08h after %0d cycles.",
                     debug_pc, debug_instruction, exec_cycles);
            write_result_json(1, exec_cycles);
        end

        $display("CPU_SIM: Finished. The GUI can now load simulation_result.json.");
        $finish;
    end

endmodule
